import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class SafeScriptEvaluator {
    public static void main(String[] args) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Safe: Input is validated before evaluation
        String userInput = "1 + 1"; // Could be user-provided input
        if (isValidExpression(userInput)) {
            try {
                Object result = engine.eval(userInput);
                System.out.println("Result: " + result);
            } catch (ScriptException e) {
                e.printStackTrace();
            }
        } else {
            System.out.println("Invalid input: evaluation not allowed.");
        }
    }

    // Helper method to validate input (basic example)
    private static boolean isValidExpression(String input) {
        // In a real-world scenario, this should be more robust
        // e.g., using a regex or a parser to ensure only allowed expressions
        return input.matches("^\\d+\\s*([+\\-*/]\\s*\\d+)*$");
    }
}
