import java.util.Scanner;

public class SecureCommandRunner {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a command to run (only 'ls' is allowed): ");

        String userInput = scanner.nextLine();

        // Secure: Only allow a known, safe command and validate input
        if ("ls".equals(userInput)) {
            try {
                // Use an array to avoid command injection via argument parsing
                Process process = Runtime.getRuntime().exec(new String[] { "ls" });
                process.waitFor();
            } catch (Exception e) {
                e.printStackTrace();
            }
        } else {
            System.out.println("Invalid command. Only 'ls' is allowed.");
        }
    }
}
// fixed
